63		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
64	
65		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
66		if err != nil || mediaType != "application/json" {
67			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
68			return
69		}
70	
71		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
72		var req postRequest
