1	// Package store persists document change batches in a SQLite database.
2	//
3	// Within a document every change has a client-supplied id. New ids receive a
4	// monotonically increasing cursor; re-posting an existing id is idempotent
5	// only when the deviceId and decoded JSON payload match, otherwise it is a
6	// conflict. Valid batches commit atomically, so cursors never repeat and no
7	// record is partially written, even under concurrent writers.
8	package store
9	
10	import (
11		"database/sql"
12		"encoding/json"
13		"errors"
14		"fmt"
15	
16		_ "modernc.org/sqlite"
17	)
18	
19	// Change is one element of an inbound batch or one row of a listing.
20	type Change struct {
21		ID       string          // client-supplied change id, unique per document
22		DeviceID string          // originating device
23		Payload  json.RawMessage // decoded JSON value, stored verbatim
24	}
25	
26	// Result reports the outcome for one element of an accepted batch.
27	type Result struct {
28		ID      string `json:"id"`
29		Created bool   `json:"created"`
30		Cursor  int64  `json:"cursor"`
31	}
32	
33	// ListedChange is one row in a ListChanges response.
34	type ListedChange struct {
35		ID       string          `json:"id"`
36		DeviceID string          `json:"deviceId"`
37		Payload  json.RawMessage `json:"payload"`
38		Cursor   int64           `json:"cursor"`
39	}
40	
41	// ErrConflict reports that a batch references an existing change id with a
42	// different deviceId or payload. The whole batch is rejected.
43	type ErrConflict struct {
44		ID string
45	}
46	
47	func (e *ErrConflict) Error() string {
48		return fmt.Sprintf("conflicting change %q for document", e.ID)
49	}
50	
51	// Store is the durable change log.
52	type Store struct {
53		db *sql.DB
54	}
55	
56	// Open opens (creating if needed) the SQLite database at path. The empty path
57	// opens an in-memory database useful for tests.
58	func Open(path string) (*Store, error) {
59		if path == "" {
60			// With a single pooled connection this is a private, per-instance
61			// in-memory database (useful for tests).
62			path = "file::memory:"
63		}
64		// _txlock=immediate makes writers acquire the write lock at BEGIN, so
65		// concurrent batches serialize without SQLITE_BUSY deadlocks.
66		dsn := path + "?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL&_foreign_keys=on"
67		db, err := sql.Open("sqlite", dsn)
68		if err != nil {
69			return nil, err
70		}
71		// One connection avoids cross-connection locking surprises; writes are
72		// serialized by the immediate transaction anyway, and SQLite concurrency
73		// for readers does not help correctness here.
74		db.SetMaxOpenConns(1)
75		s := &Store{db: db}
76		if err := s.init(); err != nil {
77			_ = db.Close()
78			return nil, err
79		}
80		return s, nil
81	}
82	
83	func (s *Store) init() error {
84		_, err := s.db.Exec(`
85	CREATE TABLE IF NOT EXISTS changes (
86		document_id TEXT NOT NULL,
87		cursor      INTEGER NOT NULL,
88		id          TEXT NOT NULL,
89		device_id   TEXT NOT NULL,
90		payload     BLOB NOT NULL,
91		PRIMARY KEY (document_id, id)
92	);
93	CREATE UNIQUE INDEX IF NOT EXISTS changes_doc_cursor_idx
94		ON changes(document_id, cursor);
95	`)
96		return err
97	}
98	
99	// Close releases the database handle.
100	func (s *Store) Close() error { return s.db.Close() }
101	
102	// PostChanges validates and commits one batch atomically.
103	//
104	// Every change must have a non-empty id; duplicate ids within the batch are
105	// rejected by the caller before reaching this point. On conflict the returned
106	// error is *ErrConflict and nothing is written. Cursors are assigned in batch
107	// order to ids that do not yet exist. Results are returned in the same order
108	// as the input.
109	func (s *Store) PostChanges(documentID string, changes []Change) ([]Result, error) {
110		tx, err := s.db.Begin()
111		if err != nil {
112			return nil, err
113		}
114		defer func() { _ = tx.Rollback() }()
115	
116		results := make([]Result, len(changes))
117	
118		// First pass: resolve every id against existing rows. A single mismatch
119		// aborts the whole batch before any cursor is allocated.
120		pending := make([]int, 0, len(changes))
121		for i, c := range changes {
122			var existingDevice string
123			var existingPayload []byte
124			var existingCursor int64
125			err := tx.QueryRow(
126				`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
127				documentID, c.ID,
128			).Scan(&existingCursor, &existingDevice, &existingPayload)
129			switch {
130			case errors.Is(err, sql.ErrNoRows):
131				pending = append(pending, i)
132			case err != nil:
133				return nil, err
134			default:
135				if existingDevice != c.DeviceID || !jsonEqual(existingPayload, c.Payload) {
136					return nil, &ErrConflict{ID: c.ID}
137				}
138				results[i] = Result{
139					ID:      c.ID,
140					Created: false,
141					Cursor:  existingCursor,
142				}
143			}
144		}
145	
146		// Allocate cursors for genuinely new ids.
147		var nextCursor int64
148		if err := tx.QueryRow(
149			`SELECT COALESCE(MAX(cursor), 0) + 1 FROM changes WHERE document_id = ?`,
150			documentID,
151		).Scan(&nextCursor); err != nil {
152			return nil, err
153		}
154		for _, i := range pending {
155			c := changes[i]
156			if _, err := tx.Exec(
157				`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
158				documentID, nextCursor, c.ID, c.DeviceID, []byte(c.Payload),
159			); err != nil {
160				return nil, err
161			}
162			results[i] = Result{
163				ID:      c.ID,
164				Created: true,
165				Cursor:  nextCursor,
166			}
167			nextCursor++
168		}
169	
170		if err := tx.Commit(); err != nil {
171			return nil, err
172		}
173		return results, nil
174	}
175	
176	// ListChanges returns at most limit changes for documentID whose cursor is
177	// greater than after, in cursor order, together with the cursor to pass as
178	// the next after value. An unknown document yields an empty list and cursor 0;
179	// a known document with no rows past after yields nextCursor == after.
180	func (s *Store) ListChanges(documentID string, after, limit int64) ([]ListedChange, int64, error) {
181		rows, err := s.db.Query(
182			`SELECT id, device_id, payload, cursor FROM changes
183			 WHERE document_id = ? AND cursor > ?
184			 ORDER BY cursor ASC
185			 LIMIT ?`,
186			documentID, after, limit,
187		)
188		if err != nil {
189			return nil, 0, err
190		}
191		defer func() { _ = rows.Close() }()
192	
193		out := make([]ListedChange, 0)
194		var maxCursor int64 = after
195		for rows.Next() {
196			var c ListedChange
197			if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
198				return nil, 0, err
199			}
200			out = append(out, c)
201			maxCursor = c.Cursor
202		}
203		if err := rows.Err(); err != nil {
204			return nil, 0, err
205		}
206	
207		// Distinguish an unknown document from a known one with nothing new:
208		// unknown documents must report nextCursor 0.
209		if len(out) == 0 {
210			var known bool
211			if err := s.db.QueryRow(
212				`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)`,
213				documentID,
214			).Scan(&known); err != nil {
215				return nil, 0, err
216			}
217			if !known {
218				return out, 0, nil
219			}
220		}
221		return out, maxCursor, nil
222	}
223	
224	// jsonEqual reports whether two payloads are equal after JSON decoding, so
225	// 1 and 1.0, or {"a":1,"b":2} and {"b":2,"a":1}, compare equal.
226	func jsonEqual(a, b json.RawMessage) bool {
227		var va, vb any
228		if err := json.Unmarshal(a, &va); err != nil {
229			return false
230		}
231		if err := json.Unmarshal(b, &vb); err != nil {
232			return false
233		}
234		return deepEqual(va, vb)
235	}
236	
237	func deepEqual(a, b any) bool {
238		switch av := a.(type) {
239		case nil:
240			return b == nil
241		case bool:
242			bv, ok := b.(bool)
243			return ok && av == bv
244		case string:
245			bv, ok := b.(string)
246			return ok && av == bv
247		case float64:
248			bv, ok := b.(float64)
249			return ok && av == bv
250		case []any:
251			bv, ok := b.([]any)
252			if !ok || len(av) != len(bv) {
253				return false
254			}
255			for i := range av {
256				if !deepEqual(av[i], bv[i]) {
257					return false
258				}
259			}
260			return true
261		case map[string]any:
262			bv, ok := b.(map[string]any)
263			if !ok || len(av) != len(bv) {
264				return false
265			}
266			for k, v := range av {
267				w, exists := bv[k]
268				if !exists || !deepEqual(v, w) {
269					return false
270				}
271			}
272			return true
273		default:
274			return false
275		}
276	}
