func TestEmptyPathOverRealServer(t *testing.T) {
	st, err := store.Open("")
	if err != nil {
		t.Fatal(err)
	}
	ts := httptest.NewServer(srvpkg.NewHandler(st))
	defer ts.Close()

	for _, c := range []struct{ method, path string }{
		{http.MethodGet, "/v1/documents//changes"},
		{http.MethodPost, "/v1/documents//changes"},
		{http.MethodPost, "/v1/documents//merge"},
	} {
		req, _ := http.NewRequest(c.method, ts.URL+c.path, strings.NewReader(`{}`))
		req.Header.Set("Content-Type", "application/json")
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			t.Fatal(err)
		}
		body := make([]byte, resp.ContentLength)
		_, _ = resp.Body.Read(body)
		resp.Body.Close()
		t.Logf("%s %s -> %d ct=%s body=%s", c.method, c.path, resp.StatusCode, resp.Header.Get("Content-Type"), body)
		if resp.StatusCode != http.StatusBadRequest {
			t.Errorf("got %d want 400", resp.StatusCode)
		}
		if !strings.Contains(resp.Header.Get("Content-Type"), "application/json") {
			t.Errorf("ct=%s want json", resp.Header.Get("Content-Type"))
		}
	}

	// Non-empty path still routes (validation then 400 for empty body, but proves no redirect/404).
	resp, err := http.Post(ts.URL+"/v1/documents/doc/merge", "application/json", strings.NewReader(`{}`))
	if err != nil {
		t.Fatal(err)
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusBadRequest {
		t.Fatalf("non-empty merge empty body = %d want 400", resp.StatusCode)
	}
}
